1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
15	//
16	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
17	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
18	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
19	// 全部样品、保管历史以及交接编号的重复提交判断。
20	type Store struct {
21		path string
22		mu   sync.Mutex
23		data *ledger
24	
25		// now 可在同包测试中替换，便于确定性地控制事件时间。
26		now func() time.Time
27	}
28	
29	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
30	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
31	func Open(path string) (*Store, error) {
32		if strings.TrimSpace(path) == "" {
33			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
34		}
35	
36		s := &Store{path: path, now: time.Now}
37	
38		raw, err := os.ReadFile(path)
39		switch {
40		case err == nil:
41			var l ledger
42			if err := json.Unmarshal(raw, &l); err != nil {
43				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
44			}
45			if l.Version != 1 {
46				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
47			}
48			if l.Samples == nil {
49				l.Samples = make(map[string]*sampleRecord)
50			}
51			if l.Transfers == nil {
52				l.Transfers = make(map[string]*transferRecord)
53			}
54			if err := validateRestored(&l); err != nil {
55				return nil, err
56			}
57			s.data = &l
58		case os.IsNotExist(err):
59			s.data = newLedger()
60			if err := s.persist(s.data); err != nil {
61				return nil, err
62			}
63		default:
64			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
65		}
66		return s, nil
67	}
68	
69	// validateRestored 校验从文件恢复的数据中交接关联是否一致。
70	// 样品的非空 pendingId 必须指向一条实际存在、尚未确认、且属于该样品的
71	// 交接；每条尚未确认的交接也必须对应一份实际存在、且 pendingId 正好指向
72	// 它的样品。待确认交接表示样品当前全部剩余量尚待指定人员接收，因此其
73	// 内容还必须与样品当前记录一致：样品未销毁、剩余量大于零、交出人等于
74	// 当前持有人、交出地点等于当前地点、交接量精确等于当前剩余量。
75	//
76	// 已确认交接属于保留的历史，不要求样品继续指向它，也不核对其与样品当前
77	// 持有人、地点或剩余量的差异（样品后来分装、移动或销毁都不能否定当时的
78	// 接收事实）；但它必须保留有效的接收信息：确认人非空且与该交接原先指定
79	// 的接收人一致，接收时间存在且非零，且按实际时刻不早于交出时间（恰好
80	// 相等合法，时区只影响表示）。集合中占用编号却为 null 的条目视为损坏，
81	// 不能当作记录不存在。任一问题都使整个文件无法恢复，绝不只加载其中
82	// 一部分，也不改动原文件。
83	func validateRestored(l *ledger) error {
84		sampleIDs := make([]string, 0, len(l.Samples))
85		for id := range l.Samples {
86			sampleIDs = append(sampleIDs, id)
87		}
88		sort.Strings(sampleIDs)
89		for _, id := range sampleIDs {
90			rec := l.Samples[id]
91			if rec == nil {
92				return fmt.Errorf("%w: 样品编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
93			}
94			if rec.PendingID == "" {
95				continue
96			}
97			tr, ok := l.Transfers[rec.PendingID]
98			switch {
99			case !ok:
100				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接不存在，无法恢复",
101					ErrInvalid, id, rec.PendingID)
102			case tr == nil:
103				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接记录为 null，无法恢复",
104					ErrInvalid, id, rec.PendingID)
105			case tr.Confirmed:
106				return fmt.Errorf("%w: 样品 %q 记着的交接 %q 已确认，不能仍是待确认，无法恢复",
107					ErrInvalid, id, rec.PendingID)
108			case tr.SampleID != id:
109				return fmt.Errorf("%w: 样品 %q 记着的待确认交接 %q 属于样品 %q，无法恢复",
110					ErrInvalid, id, rec.PendingID, tr.SampleID)
111			}
112			if err := validatePendingContent(id, rec, tr); err != nil {
113				return err
114			}
115		}
116	
117		transferIDs := make([]string, 0, len(l.Transfers))
118		for id := range l.Transfers {
119			transferIDs = append(transferIDs, id)
120		}
121		sort.Strings(transferIDs)
122		for _, id := range transferIDs {
123			rec := l.Transfers[id]
124			if rec == nil {
125				return fmt.Errorf("%w: 交接编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
126			}
127			if rec.Confirmed {
128				if err := validateConfirmedReceipt(rec); err != nil {
129					return err
130				}
131				continue
132			}
133			sample, ok := l.Samples[rec.SampleID]
134			switch {
135			case !ok:
136				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 不存在，无法恢复",
137					ErrInvalid, id, rec.SampleID)
138			case sample == nil:
139				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 记录为 null，无法恢复",
140					ErrInvalid, id, rec.SampleID)
141			case sample.PendingID != id:
142				return fmt.Errorf("%w: 待确认交接 %q 的样品 %q 并未记着该交接编号，无法恢复",
143					ErrInvalid, id, rec.SampleID)
144			default:
145				if err := validatePendingContent(rec.SampleID, sample, rec); err != nil {
146					return err
147				}
148			}
149		}
150		return nil
151	}
152	
153	// validatePendingContent 核对一条待确认交接的内容是否与样品当前记录一致。
154	// 待确认交接表示样品当前全部剩余量尚待指定人员接收：样品必须未销毁且
155	// 剩余量大于零，交接的交出人、交出地点和交接量必须分别精确等于样品的
156	// 当前持有人、当前地点和当前剩余量。任一不符都返回包装了 ErrInvalid 的
157	// 错误，并在信息中写明样品编号、交接编号以及冲突项（人员、地点、数量
158	// 或销毁状态）；数量冲突同时列出双方数量，统一按三位小数毫升展示。
159	func validatePendingContent(sampleID string, sample *sampleRecord, tr *transferRecord) error {
160		switch {
161		case sample.Destroyed != nil:
162			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品已销毁，无法恢复",
163				ErrInvalid, sampleID, tr.ID)
164		case sample.Remaining <= 0:
165			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 仍存在，但样品当前剩余量为 %s 毫升（未销毁），无法恢复",
166				ErrInvalid, sampleID, tr.ID, formatUnits(sample.Remaining))
167		case tr.FromHolder != sample.Holder:
168			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出人 %q 与样品当前持有人 %q 不一致，无法恢复",
169				ErrInvalid, sampleID, tr.ID, tr.FromHolder, sample.Holder)
170		case tr.FromLocation != sample.Location:
171			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交出地点 %q 与样品当前地点 %q 不一致，无法恢复",
172				ErrInvalid, sampleID, tr.ID, tr.FromLocation, sample.Location)
173		case tr.Qty != sample.Remaining:
174			return fmt.Errorf("%w: 样品 %q 的待确认交接 %q 的交接量 %s 毫升与样品当前剩余量 %s 毫升不一致，无法恢复",
175				ErrInvalid, sampleID, tr.ID, formatUnits(tr.Qty), formatUnits(sample.Remaining))
176		}
177		return nil
178	}
179	
180	// validateConfirmedReceipt 核对一条已确认交接是否保留了有效的接收事实。
181	// 已确认表示样品确实完成过一次转手，因此确认人必须非空（去首尾空白后）
182	// 且与该交接原先指定的接收人完全一致，接收时间必须存在且不是零时间，
183	// 并按实际时刻不早于交出时间（恰好相等合法；不同时区表示同一时刻也算
184	// 相等，时间倒置用 Before 判断而非比较时区偏移后的字面值）。任一不符
185	// 都返回包装了 ErrInvalid 的错误，信息写明交接编号、关联样品编号以及
186	// 具体问题（缺少/空白确认人、确认人不符、缺少或零值接收时间、时间倒置），
187	// 绝不靠补写确认人、猜测接收时间或改回待确认来接受异常记录。
188	func validateConfirmedReceipt(tr *transferRecord) error {
189		switch {
190		case tr.ConfirmedBy == "":
191			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少确认人，无法恢复",
192				ErrInvalid, tr.ID, tr.SampleID)
193		case strings.TrimSpace(tr.ConfirmedBy) == "":
194			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人不能只有空白，无法恢复",
195				ErrInvalid, tr.ID, tr.SampleID)
196		case tr.ConfirmedBy != tr.ToHolder:
197			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的确认人 %q 与原定接收人 %q 不一致，无法恢复",
198				ErrInvalid, tr.ID, tr.SampleID, tr.ConfirmedBy, tr.ToHolder)
199		}
200		switch {
201		case tr.ReceivedAt == nil:
202			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）缺少接收时间，无法恢复",
203				ErrInvalid, tr.ID, tr.SampleID)
204		case tr.ReceivedAt.IsZero():
205			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间为零值，无法恢复",
206				ErrInvalid, tr.ID, tr.SampleID)
207		case tr.ReceivedAt.Before(tr.HandedOverAt):
208			return fmt.Errorf("%w: 已确认交接 %q（样品 %q）的接收时间 %s 早于交出时间 %s，无法恢复",
209				ErrInvalid, tr.ID, tr.SampleID,
210				tr.ReceivedAt.Format(time.RFC3339), tr.HandedOverAt.Format(time.RFC3339))
211		}
212		return nil
213	}
214	
215	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
216	// 避免进程中断留下半截数据。
217	func (s *Store) persist(l *ledger) error {
218		raw, err := json.MarshalIndent(l, "", "  ")
219		if err != nil {
220			return fmt.Errorf("编码本地样品数据失败: %w", err)
221		}
222	
223		dir := filepath.Dir(s.path)
224		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
225		if err != nil {
226			return fmt.Errorf("创建临时数据文件失败: %w", err)
227		}
228		tmpName := tmp.Name()
229		defer os.Remove(tmpName)
230	
231		if _, err := tmp.Write(raw); err != nil {
232			tmp.Close()
233			return fmt.Errorf("写入临时数据文件失败: %w", err)
234		}
235		if err := tmp.Close(); err != nil {
236			return fmt.Errorf("关闭临时数据文件失败: %w", err)
237		}
238		if err := os.Rename(tmpName, s.path); err != nil {
239			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
240		}
241		return nil
242	}
243	
244	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
245	// 已通过全部校验；落盘失败时内存状态保持不变。
246	func (s *Store) commit(candidate *ledger) error {
247		if err := s.persist(candidate); err != nil {
248			return err
249		}
250		s.data = candidate
251		return nil
252	}
253	
254	// RegisterInput 是登记原样的入参。
255	type RegisterInput struct {
256		// ID 为样品编号，在这份数据内唯一，去空白后非空。
257		ID string
258		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
259		Qty string
260		// Holder 为初始持有人，去空白后非空。
261		Holder string
262		// Location 为初始地点，去空白后非空。
263		Location string
264	}
265	
266	// Register 登记一份原样。编号重复等冲突返回包装了 ErrConflict 的错误，
267	// 且不会写入任何记录。
268	func (s *Store) Register(in RegisterInput) (*Sample, error) {
269		s.mu.Lock()
270		defer s.mu.Unlock()
271	
272		id, err := trimRequired("样品编号", in.ID)
273		if err != nil {
274			return nil, err
275		}
276		holder, err := trimRequired("持有人", in.Holder)
277		if err != nil {
278			return nil, err
279		}
280		location, err := trimRequired("地点", in.Location)
281		if err != nil {
282			return nil, err
283		}
284		qty, err := parseQuantity(in.Qty)
285		if err != nil {
286			return nil, err
287		}
288		if _, exists := s.data.Samples[id]; exists {
289			return nil, fmt.Errorf("%w: 样品编号 %q 已存在", ErrConflict, id)
290		}
291	
292		candidate := s.data.deepCopy()
293		now := s.now().UTC()
294		candidate.Samples[id] = &sampleRecord{
295			ID:        id,
296			Initial:   qty,
297			Remaining: qty,
298			Holder:    holder,
299			Location:  location,
300			Children:  []string{},
301			History: []historyRecord{{
302				Kind:     "register",
303				Time:     now,
304				Holder:   holder,
305				Location: location,
306				Detail:   "登记原样",
307			}},
308		}
309		if err := s.commit(candidate); err != nil {
310			return nil, err
311		}
312		return buildSampleView(candidate.Samples[id], candidate), nil
313	}
314	
315	// SplitPart 是一次分装中的一个子样。
316	type SplitPart struct {
317		// ID 为子样编号，在这份数据内唯一，去空白后非空。
318		ID string
319		// Qty 为该子样数量（毫升），大于零、最多三位小数。
320		Qty string
321	}
322	
323	// SplitInput 是一次分装的入参；一次分装可以同时创建多个子样。
324	type SplitInput struct {
325		// ParentID 为来源样品编号。
326		ParentID string
327		// Parts 为本次要创建的全部子样，至少一个。
328		Parts []SplitPart
329	}
330	
331	// Split 执行一次原子分装。任一子样编号重复、数量不合法或子样总量超过
332	// 来源样品剩余量时，整次分装都不生效。成功后来源样品按整数刻度精确
333	// 扣减，子样继承当时的持有人和地点，并可继续分装。
334	//
335	// 返回来源样品的最新视图；子样可通过 GetSample 分别查询。
336	func (s *Store) Split(in SplitInput) (*Sample, error) {
337		s.mu.Lock()
338		defer s.mu.Unlock()
339	
340		parentID, err := trimRequired("来源样品编号", in.ParentID)
341		if err != nil {
342			return nil, err
343		}
344		if len(in.Parts) == 0 {
345			return nil, fmt.Errorf("%w: 一次分装至少要创建一个子样", ErrInvalid)
346		}
347	
348		parent, ok := s.data.Samples[parentID]
349		if !ok {
350			return nil, fmt.Errorf("%w: 来源样品 %q 不存在", ErrNotFound, parentID)
351		}
352	
353		// 先在局部完成全部校验，任何一项不通过都直接返回，不动状态。
354		type parsedPart struct {
355			id  string
356			qty int64
357		}
358		parsed := make([]parsedPart, 0, len(in.Parts))
359		seen := make(map[string]struct{}, len(in.Parts))
360		var total int64
361		for _, p := range in.Parts {
362			id, err := trimRequired("子样编号", p.ID)
363			if err != nil {
364				return nil, err
365			}
366			if _, dup := seen[id]; dup {
367				return nil, fmt.Errorf("%w: 本次分装中子样编号 %q 重复", ErrInvalid, id)
368			}
369			if _, exists := s.data.Samples[id]; exists {
370				return nil, fmt.Errorf("%w: 子样编号 %q 已存在", ErrConflict, id)
371			}
372			if id == parentID {
373				return nil, fmt.Errorf("%w: 子样编号 %q 不能与来源样品相同", ErrInvalid, id)
374			}
375			qty, err := parseQuantity(p.Qty)
376			if err != nil {
377				return nil, err
378			}
379			seen[id] = struct{}{}
380			parsed = append(parsed, parsedPart{id: id, qty: qty})
381			total += qty
382			if total < 0 {
383				return nil, fmt.Errorf("%w: 子样总量超出可表示范围", ErrInvalid)
384			}
385		}
386	
387		if parent.Destroyed != nil {
388			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能再分装", ErrConflict, parentID)
389		}
390		if parent.PendingID != "" {
391			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能分装",
392				ErrConflict, parentID, parent.PendingID)
393		}
394		if parent.Remaining == 0 {
395			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能再分装", ErrConflict, parentID)
396		}
397		if total > parent.Remaining {
398			return nil, fmt.Errorf("%w: 子样总量 %s 毫升超过样品 %q 的剩余量 %s 毫升",
399				ErrConflict, formatUnits(total), parentID, formatUnits(parent.Remaining))
400		}
401	
402		candidate := s.data.deepCopy()
403		cpParent := candidate.Samples[parentID]
404		now := s.now().UTC()
405	
406		childIDs := make([]string, 0, len(parsed))
407		for _, p := range parsed {
408			childIDs = append(childIDs, p.id)
409			candidate.Samples[p.id] = &sampleRecord{
410				ID:        p.id,
411				ParentID:  parentID,
412				Initial:   p.qty,
413				Remaining: p.qty,
414				Holder:    cpParent.Holder,
415				Location:  cpParent.Location,
416				Children:  []string{},
417				History: []historyRecord{{
418					Kind:     "split",
419					Time:     now,
420					Holder:   cpParent.Holder,
421					Location: cpParent.Location,
422					Detail:   fmt.Sprintf("由样品 %s 分装", parentID),
423				}},
424			}
425		}
426		cpParent.Remaining -= total
427		cpParent.Children = append(cpParent.Children, childIDs...)
428		cpParent.History = append(cpParent.History, historyRecord{
429			Kind:     "split",
430			Time:     now,
431			Holder:   cpParent.Holder,
432			Location: cpParent.Location,
433			Detail:   fmt.Sprintf("分装创建子样 %s", strings.Join(childIDs, ", ")),
434		})
435	
436		if err := s.commit(candidate); err != nil {
437			return nil, err
438		}
439		return buildSampleView(cpParent, candidate), nil
440	}
441	
442	// HandoverInput 是发起交接（交出）的入参。
443	type HandoverInput struct {
444		// TransferID 为本次交接编号，在本地数据中唯一，去空白后非空。
445		TransferID string
446		// SampleID 为要交出的样品编号。
447		SampleID string
448		// FromHolder 为交出人，必须与样品当前持有人完全一致（比较前对入参去空白）。
449		FromHolder string
450		// FromLocation 为交出地点，必须与样品当前地点完全一致。
451		FromLocation string
452		// ToHolder 为指定接收人，不能与交出人相同。
453		ToHolder string
454		// ToLocation 为目的地点。
455		ToLocation string
456		// HandedOverAt 为交出时间。
457		HandedOverAt time.Time
458	}
459	
460	// Handover 发起一次交接：转移该样品的全部剩余量，交接进入待确认状态，
461	// 原持有人和地点保持不变，直到指定接收人在目的地点确认。
462	//
463	// 交接编号已存在时：内容（样品、人员、地点、时间）完全一致则原样返回
464	// 既有交接（无论是否已确认）；任一内容不同则拒绝。
465	func (s *Store) Handover(in HandoverInput) (*TransferView, error) {
466		s.mu.Lock()
467		defer s.mu.Unlock()
468	
469		transferID, err := trimRequired("交接编号", in.TransferID)
470		if err != nil {
471			return nil, err
472		}
473		sampleID, err := trimRequired("样品编号", in.SampleID)
474		if err != nil {
475			return nil, err
476		}
477		fromHolder, err := trimRequired("交出人", in.FromHolder)
478		if err != nil {
479			return nil, err
480		}
481		fromLocation, err := trimRequired("交出地点", in.FromLocation)
482		if err != nil {
483			return nil, err
484		}
485		toHolder, err := trimRequired("接收人", in.ToHolder)
486		if err != nil {
487			return nil, err
488		}
489		toLocation, err := trimRequired("目的地点", in.ToLocation)
490		if err != nil {
491			return nil, err
492		}
493		if in.HandedOverAt.IsZero() {
494			return nil, fmt.Errorf("%w: 交出时间不能为空", ErrInvalid)
495		}
496		handedAt := in.HandedOverAt.UTC()
497	
498		if existing, ok := s.data.Transfers[transferID]; ok {
499			if !sameHandoverRequest(existing, sampleID, fromHolder, fromLocation, toHolder, toLocation, handedAt) {
500				return nil, fmt.Errorf("%w: 交接编号 %q 已被内容不同的交接使用", ErrConflict, transferID)
501			}
502			// 完全相同的重复提交：返回原交接，不增加任何记录。
503			return buildTransferView(existing), nil
504		}
505	
506		sample, ok := s.data.Samples[sampleID]
507		if !ok {
508			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
509		}
510		if sample.Destroyed != nil {
511			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能发起新的交接", ErrConflict, sampleID)
512		}
513		if sample.Remaining == 0 {
514			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能发起交接", ErrConflict, sampleID)
515		}
516		if sample.PendingID != "" {
517			return nil, fmt.Errorf("%w: 样品 %q 已存在待确认交接 %s",
518				ErrConflict, sampleID, sample.PendingID)
519		}
520		if sample.Holder != fromHolder {
521			return nil, fmt.Errorf("%w: 交出人 %q 与样品 %q 当前持有人 %q 不一致",
522				ErrInvalid, fromHolder, sampleID, sample.Holder)
523		}
524		if sample.Location != fromLocation {
525			return nil, fmt.Errorf("%w: 交出地点 %q 与样品 %q 当前地点 %q 不一致",
526				ErrInvalid, fromLocation, sampleID, sample.Location)
527		}
528		if toHolder == fromHolder {
529			return nil, fmt.Errorf("%w: 接收人不能与交出人 %q 相同", ErrInvalid, fromHolder)
530		}
531	
532		candidate := s.data.deepCopy()
533		rec := &transferRecord{
534			ID:           transferID,
535			SampleID:     sampleID,
536			FromHolder:   fromHolder,
537			FromLocation: fromLocation,
538			ToHolder:     toHolder,
539			ToLocation:   toLocation,
540			Qty:          sample.Remaining,
541			HandedOverAt: handedAt,
542		}
543		candidate.Transfers[transferID] = rec
544		cpSample := candidate.Samples[sampleID]
545		cpSample.PendingID = transferID
546		cpSample.History = append(cpSample.History, historyRecord{
547			Kind:     "transfer-out",
548			Time:     handedAt,
549			Holder:   fromHolder,
550			Location: fromLocation,
551			Detail:   fmt.Sprintf("发起交接 %s，待 %s 在 %s 接收", transferID, toHolder, toLocation),
552		})
553	
554		if err := s.commit(candidate); err != nil {
555			return nil, err
556		}
557		return buildTransferView(rec), nil
558	}
559	
560	// sameHandoverRequest 判断已存交接与本次请求的内容是否完全相同。
561	func sameHandoverRequest(t *transferRecord, sampleID, fromHolder, fromLocation, toHolder, toLocation string, handedAt time.Time) bool {
562		return t.SampleID == sampleID &&
563			t.FromHolder == fromHolder &&
564			t.FromLocation == fromLocation &&
565			t.ToHolder == toHolder &&
566			t.ToLocation == toLocation &&
567			t.HandedOverAt.Equal(handedAt)
568	}
569	
570	// ConfirmInput 是确认接收的入参。
571	type ConfirmInput struct {
572		// TransferID 为待确认的交接编号。
573		TransferID string
574		// Receiver 为实际接收人，必须是发起时指定的接收人。
575		Receiver string
576		// AtLocation 为接收地点，必须是发起时的目的地点。
577		AtLocation string
578		// ReceivedAt 为接收时间，不能早于交出时间。
579		ReceivedAt time.Time
580	}
581	
582	// Confirm 由指定接收人在目的地点确认接收。确认后样品的持有人和地点
583	// 才真正改变，待确认状态结束。
584	//
585	// 对已确认交接重复提交完全相同的接收信息（接收人、地点、时间）时，
586	// 返回原结果且不增加转手记录；信息不同则拒绝。
587	func (s *Store) Confirm(in ConfirmInput) (*TransferView, error) {
588		s.mu.Lock()
589		defer s.mu.Unlock()
590	
591		transferID, err := trimRequired("交接编号", in.TransferID)
592		if err != nil {
593			return nil, err
594		}
595		receiver, err := trimRequired("接收人", in.Receiver)
596		if err != nil {
597			return nil, err
598		}
599		atLocation, err := trimRequired("接收地点", in.AtLocation)
600		if err != nil {
601			return nil, err
602		}
603		if in.ReceivedAt.IsZero() {
604			return nil, fmt.Errorf("%w: 接收时间不能为空", ErrInvalid)
605		}
606		receivedAt := in.ReceivedAt.UTC()
607	
608		rec, ok := s.data.Transfers[transferID]
609		if !ok {
610			// 明确的不存在错误，绝不顺带创建交接。
611			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
612		}
613	
614		if rec.Confirmed {
615			same := rec.ConfirmedBy == receiver &&
616				rec.ToLocation == atLocation &&
617				rec.ReceivedAt != nil && rec.ReceivedAt.Equal(receivedAt)
618			if !same {
619				return nil, fmt.Errorf("%w: 交接 %q 已确认，接收信息与原确认不一致", ErrConflict, transferID)
620			}
621			return buildTransferView(rec), nil
622		}
623	
624		if receiver != rec.ToHolder {
625			return nil, fmt.Errorf("%w: 只有指定接收人 %q 能确认交接 %q，实际确认人为 %q",
626				ErrConflict, rec.ToHolder, transferID, receiver)
627		}
628		if atLocation != rec.ToLocation {
629			return nil, fmt.Errorf("%w: 必须在目的地点 %q 确认交接 %q，实际地点为 %q",
630				ErrConflict, rec.ToLocation, transferID, atLocation)
631		}
632		if receivedAt.Before(rec.HandedOverAt) {
633			return nil, fmt.Errorf("%w: 接收时间不能早于交出时间 %s",
634				ErrInvalid, rec.HandedOverAt.Format(time.RFC3339))
635		}
636	
637		candidate := s.data.deepCopy()
638		cp := candidate.Transfers[transferID]
639		cp.Confirmed = true
640		cp.ConfirmedBy = receiver
641		receivedAtCopy := receivedAt
642		cp.ReceivedAt = &receivedAtCopy
643	
644		sample := candidate.Samples[cp.SampleID]
645		sample.Holder = receiver
646		sample.Location = atLocation
647		sample.PendingID = ""
648		sample.History = append(sample.History, historyRecord{
649			Kind:     "transfer-in",
650			Time:     receivedAt,
651			Holder:   receiver,
652			Location: atLocation,
653			Detail:   fmt.Sprintf("交接 %s 确认接收（交出时间 %s）", transferID, cp.HandedOverAt.Format(time.RFC3339)),
654		})
655	
656		if err := s.commit(candidate); err != nil {
657			return nil, err
658		}
659		return buildTransferView(cp), nil
660	}
661	
662	// DestroyInput 是销毁样品全部剩余量的入参；销毁不接受部分销毁。
663	type DestroyInput struct {
664		// SampleID 为样品编号。
665		SampleID string
666		// Operator 为操作人，去空白后必须与样品当前持有人一致。
667		Operator string
668		// Location 为销毁所在地点，去空白后必须与样品当前地点一致。
669		Location string
670		// At 为销毁时间，不能为零，也不能早于该样品任何已有保管历史的时间。
671		At time.Time
672		// Reason 为销毁原因，去空白后非空。
673		Reason string
674	}
675	
676	// Destroy 销毁该编号样品当时的全部剩余量（不接受部分销毁）。成功后
677	// 剩余量变为 0.000，初始量、来源关系、子样列表与原有保管历史保留，
678	// 持有人和地点保留为销毁前的最后记录，并在保管历史末尾追加一次销毁
679	// 事件；返回该样品的最新查询结果。
680	//
681	// 已销毁样品重复提交完全相同的操作人、地点、时间和原因时，返回原销毁
682	// 结果且不再追加历史；文本按去首尾空白后的内容比较，时间按实际时刻
683	// 比较。任一项不同则返回 ErrConflict，不覆盖原记录。
684	func (s *Store) Destroy(in DestroyInput) (*Sample, error) {
685		s.mu.Lock()
686		defer s.mu.Unlock()
687	
688		sampleID, err := trimRequired("样品编号", in.SampleID)
689		if err != nil {
690			return nil, err
691		}
692		operator, err := trimRequired("操作人", in.Operator)
693		if err != nil {
694			return nil, err
695		}
696		location, err := trimRequired("所在地点", in.Location)
697		if err != nil {
698			return nil, err
699		}
700		reason, err := trimRequired("销毁原因", in.Reason)
701		if err != nil {
702			return nil, err
703		}
704		if in.At.IsZero() {
705			return nil, fmt.Errorf("%w: 销毁时间不能为空", ErrInvalid)
706		}
707		at := in.At.UTC()
708	
709		rec, ok := s.data.Samples[sampleID]
710		if !ok {
711			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
712		}
713	
714		// 已销毁：只接受与首次销毁完全相同的重复提交，原样返回且不再追加历史。
715		if rec.Destroyed != nil {
716			if !sameDestruction(rec.Destroyed, operator, location, at, reason) {
717				return nil, fmt.Errorf("%w: 样品 %q 已销毁，本次销毁信息与原销毁记录不一致",
718					ErrConflict, sampleID)
719			}
720			return buildSampleView(rec, s.data), nil
721		}
722	
723		// 未销毁样品的状态冲突（持有人/地点不匹配按入参语义归入冲突类）。
724		if operator != rec.Holder {
725			return nil, fmt.Errorf("%w: 操作人 %q 与样品 %q 当前持有人 %q 不一致",
726				ErrConflict, operator, sampleID, rec.Holder)
727		}
728		if location != rec.Location {
729			return nil, fmt.Errorf("%w: 销毁地点 %q 与样品 %q 当前地点 %q 不一致",
730				ErrConflict, location, sampleID, rec.Location)
731		}
732		if rec.PendingID != "" {
733			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能销毁",
734				ErrConflict, sampleID, rec.PendingID)
735		}
736		if rec.Remaining == 0 {
737			return nil, fmt.Errorf("%w: 样品 %q 剩余量已为零且未销毁，不能再销毁",
738				ErrConflict, sampleID)
739		}
740		for _, h := range rec.History {
741			if at.Before(h.Time) {
742				return nil, fmt.Errorf("%w: 销毁时间不能早于样品 %q 已有保管历史的时间 %s",
743					ErrInvalid, sampleID, h.Time.Format(time.RFC3339))
744			}
745		}
746	
747		candidate := s.data.deepCopy()
748		cp := candidate.Samples[sampleID]
749		destroyedQty := cp.Remaining
750		cp.Remaining = 0
751		cp.Destroyed = &destructionRecord{
752			Operator: operator,
753			Location: location,
754			At:       at,
755			Reason:   reason,
756			Qty:      destroyedQty,
757		}
758		// 持有人和地点保留为销毁前的最后记录，仅在历史末尾追加销毁事件。
759		cp.History = append(cp.History, historyRecord{
760			Kind:     "destroy",
761			Time:     at,
762			Holder:   operator,
763			Location: location,
764			Detail:   fmt.Sprintf("销毁全部剩余量 %s 毫升，原因：%s", formatUnits(destroyedQty), reason),
765		})
766	
767		if err := s.commit(candidate); err != nil {
768			return nil, err
769		}
770		return buildSampleView(cp, candidate), nil
771	}
772	
773	// sameDestruction 判断本次销毁请求与已有销毁记录是否完全相同。
774	// 文本字段均已去首尾空白，时间按实际时刻（Equal）比较。
775	func sameDestruction(d *destructionRecord, operator, location string, at time.Time, reason string) bool {
776		return d.Operator == operator &&
777			d.Location == location &&
778			d.At.Equal(at) &&
779			d.Reason == reason
780	}
781	
782	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
783	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
784	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
785	func (s *Store) GetSample(id string) (*Sample, error) {
786		s.mu.Lock()
787		defer s.mu.Unlock()
788	
789		sampleID, err := trimRequired("样品编号", id)
790		if err != nil {
791			return nil, err
792		}
793		rec, ok := s.data.Samples[sampleID]
794		if !ok {
795			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
796		}
797		return buildSampleView(rec, s.data), nil
798	}
799	
800	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
801	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
802	func (s *Store) GetTransfer(id string) (*TransferView, error) {
803		s.mu.Lock()
804		defer s.mu.Unlock()
805	
806		transferID, err := trimRequired("交接编号", id)
807		if err != nil {
808			return nil, err
809		}
810		rec, ok := s.data.Transfers[transferID]
811		if !ok {
812			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
813		}
814		return buildTransferView(rec), nil
815	}
816	
817	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
818	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
819		children := append([]string{}, r.Children...)
820		history := make([]History, 0, len(r.History))
821		for _, h := range r.History {
822			history = append(history, History{
823				Kind:     h.Kind,
824				Time:     h.Time,
825				Holder:   h.Holder,
826				Location: h.Location,
827				Detail:   h.Detail,
828			})
829		}
830		v := &Sample{
831			ID:         r.ID,
832			ParentID:   r.ParentID,
833			InitialQty: formatUnits(r.Initial),
834			Remaining:  formatUnits(r.Remaining),
835			Holder:     r.Holder,
836			Location:   r.Location,
837			Children:   children,
838			History:    history,
839		}
840		if r.PendingID != "" {
841			if t, ok := l.Transfers[r.PendingID]; ok {
842				v.PendingTransfer = buildTransferView(t)
843			}
844		}
845		if r.Destroyed != nil {
846			v.Destruction = &Destruction{
847				Operator: r.Destroyed.Operator,
848				Location: r.Destroyed.Location,
849				At:       r.Destroyed.At,
850				Reason:   r.Destroyed.Reason,
851				Qty:      formatUnits(r.Destroyed.Qty),
852			}
853		}
854		return v
855	}
856	
857	// buildTransferView 把内部交接记录转换为对外视图。
858	func buildTransferView(r *transferRecord) *TransferView {
859		v := &TransferView{
860			TransferID:   r.ID,
861			SampleID:     r.SampleID,
862			FromHolder:   r.FromHolder,
863			FromLocation: r.FromLocation,
864			ToHolder:     r.ToHolder,
865			ToLocation:   r.ToLocation,
866			Qty:          formatUnits(r.Qty),
867			HandedOverAt: r.HandedOverAt,
868			Confirmed:    r.Confirmed,
869			ConfirmedBy:  r.ConfirmedBy,
870		}
871		if r.ReceivedAt != nil {
872			rx := *r.ReceivedAt
873			v.ReceivedAt = &rx
874			v.ConfirmedAt = r.ToLocation
875		}
876		return v
877	}
878

