168			ToHolder: "x", ToLocation: "y", HandedOverAt: at,
169		}); err != nil {
170			t.Fatal(err)
171		}
172		if _, err := s.Destroy(DestroyInput{
173			SampleID: "P", Operator: "h", Location: "l",
174			At: at.Add(time.Hour), Reason: "r",
175		}); !errors.Is(err, ErrConflict) {
176			t.Fatalf("有待确认交接时销毁应返回 ErrConflict, got %v", err)
177		}
178		got, _ := s.GetSample("P")
179		if got.Destruction != nil || got.PendingTransfer == nil || got.Remaining != "1.000" {
