205	// TestDestroyIdempotent 已销毁样品重复提交相同信息返回原结果，不追加历史；
206	// 改变任一项返回 ErrConflict，不覆盖原记录。
207	func TestDestroyIdempotent(t *testing.T) {
208		s, _ := fixedStore(t)
209		mustRegister(t, s, "P", "2.500", "张三", "实验室A")
210		at := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
211	
212		in := DestroyInput{
213			SampleID: "P", Operator: "张三", Location: "实验室A",
214			At: at, Reason: "污染",
215		}
216		first, err := s.Destroy(in)
217		if err != nil {
218			t.Fatal(err)
219		}
220	
221		// 文本带首尾空白、时间用不同时区表示同一时刻，仍视为完全相同。
222		same := in
223		same.Operator = " 张三 "
224		same.Location = "实验室A "
225		same.Reason = " 污染 "
226		same.At = at.In(time.FixedZone("UTC+8", 8*3600))
227		again, err := s.Destroy(same)
228		if err != nil {
229			t.Fatalf("完全相同的重复提交应返回原结果, got %v", err)
230		}
231		if again.Remaining != first.Remaining || again.Destruction == nil ||
232			again.Destruction.Qty != "2.500" {
233			t.Fatalf("重复提交返回内容错误: %+v", again)
234		}
235		if len(again.History) != len(first.History) {
236			t.Fatalf("重复提交不得追加历史: first=%d again=%d",
237				len(first.History), len(again.History))
238		}
239	
240		// 改变任一项都返回 ErrConflict，且不覆盖原记录。
241		mutCases := map[string]func(DestroyInput) DestroyInput{
242			"操作人不同": func(i DestroyInput) DestroyInput { i.Operator = "李四"; return i },
243			"地点不同":  func(i DestroyInput) DestroyInput { i.Location = "实验室B"; return i },
244			"时间不同":  func(i DestroyInput) DestroyInput { i.At = at.Add(time.Second); return i },
245			"原因不同":  func(i DestroyInput) DestroyInput { i.Reason = "过期"; return i },
246		}
247		for name, mut := range mutCases {
248			t.Run(name, func(t *testing.T) {
249				if _, err := s.Destroy(mut(in)); !errors.Is(err, ErrConflict) {
250					t.Fatalf("want ErrConflict, got %v", err)
251				}
252			})
253		}
254		got, _ := s.GetSample("P")
255		if got.Destruction.Operator != "张三" || got.Destruction.Location != "实验室A" ||
256			got.Destruction.Reason != "污染" || !got.Destruction.At.Equal(at) {
257			t.Fatalf("原销毁记录被覆盖: %+v", got.Destruction)
258		}
259		if len(got.History) != len(first.History) {
260			t.Fatalf("被拒绝的重复提交不得追加历史")
261		}
262	}
