12	// 数量上限相关常量：内部以千分之一毫升的 int64 保存，最大可接受数量
13	// 9223372036854775.807 毫升恰好是 math.MaxInt64 个最小刻度。
14	const (
15		maxQtyString   = "9223372036854775.807" // 上限本身，登记应成功
