21	// openBoundaryStore 打开一个使用确定时钟的临时数据，并返回其落盘路径，
22	// 便于在大数量分装后重新打开校验持久化结果。
23	func openBoundaryStore(t *testing.T) (*Store, string) {
24		t.Helper()
25		path := filepath.Join(t.TempDir(), "data.json")
26		s, err := Open(path)
27		if err != nil {
