31		return s, path
32	}
33	
34	// TestSplitAtMaximumQuantityStaysPrecise 回归大数量下的精确分装：
35	// 以上限 9223372036854775.807 毫升登记原样，先分出仅少 0.001 的子样，
36	// 再分出最后的 0.001；整个过程不能因为数值很大而丢掉最后一位小数。
37	func TestSplitAtMaximumQuantityStaysPrecise(t *testing.T) {
38		s, path := openBoundaryStore(t)
39	
40		const (
41			parentID = "P"
42			firstID  = "C1"
43			lastID   = "C2"
44		)
45	
46		// 以当前可接受的最大数量登记原样，应成功且查询逐位一致。
47		reg := mustRegister(t, s, parentID, maxQtyString, " 张三 ", " 实验室A ")
48		if reg.InitialQty != maxQtyString || reg.Remaining != maxQtyString {
49			t.Fatalf("上限数量登记后显示不一致: init=%s remaining=%s want %s",
50				reg.InitialQty, reg.Remaining, maxQtyString)
51		}
52		if reg.Holder != "张三" || reg.Location != "实验室A" {
53			t.Fatalf("持有人地点应去空白: %+v", reg)
54		}
55	
56		// 分出 9223372036854775.806：来源必须恰好剩余 0.001，初始量保持登记值。
57		parent, err := s.Split(SplitInput{ParentID: parentID, Parts: []SplitPart{
58			{ID: firstID, Qty: belowMaxString},
59		}})
60		if err != nil {
61			t.Fatalf("接近上限的大数量分装应成功: %v", err)
62		}
63		if parent.Remaining != "0.001" {
64			t.Fatalf("分出 %s 后来源应恰好剩余 0.001, got %s", belowMaxString, parent.Remaining)
65		}
66		if parent.InitialQty != maxQtyString {
67			t.Fatalf("分装不得改变来源初始量: got %s want %s", parent.InitialQty, maxQtyString)
68		}
69		if len(parent.Children) != 1 || parent.Children[0] != firstID {
70			t.Fatalf("来源子样列表应按分装顺序记录: %v", parent.Children)
71		}
72	
73		// 子样的初始量和剩余量都必须与请求逐位一致，不能丢掉最后一位小数，
74		// 来源关系、持有人和地点与分装时一致。
75		first, err := s.GetSample(firstID)
76		if err != nil {
77			t.Fatalf("大数量子样应可查询: %v", err)
78		}
79		if first.InitialQty != belowMaxString || first.Remaining != belowMaxString {
80			t.Fatalf("大数量子样数量不精确: init=%s remaining=%s want %s",
81				first.InitialQty, first.Remaining, belowMaxString)
82		}
83		if first.ParentID != parentID || first.Holder != "张三" || first.Location != "实验室A" {
84			t.Fatalf("大数量子样继承关系错误: %+v", first)
85		}
86		if len(first.History) != 1 || first.History[0].Kind != "split" {
87			t.Fatalf("大数量子样保管历史错误: %+v", first.History)
88		}
89	
90		// 对同一来源接着分出最后 0.001：剩余量准确变为 0.000，初始量仍为登记值。
91		parent, err = s.Split(SplitInput{ParentID: parentID, Parts: []SplitPart{
92			{ID: lastID, Qty: "0.001"},
93		}})
94		if err != nil {
95			t.Fatalf("分出最后 0.001 应成功: %v", err)
96		}
97		if parent.Remaining != "0.000" {
98			t.Fatalf("分出最后 0.001 后剩余应为 0.000, got %s", parent.Remaining)
99		}
100		if parent.InitialQty != maxQtyString {
101			t.Fatalf("用尽后来源初始量仍应保留登记值: got %s want %s",
102				parent.InitialQty, maxQtyString)
103		}
104		// 分装用尽而非销毁：不应出现销毁信息。
105		if parent.Destruction != nil {
106			t.Fatalf("分装用尽不应带销毁记录: %+v", parent.Destruction)
107		}
108		if got := parent.Children; len(got) != 2 || got[0] != firstID || got[1] != lastID {
109			t.Fatalf("子样应按分装顺序记录编号: %v", got)
110		}
111		if len(parent.History) != 3 {
112			t.Fatalf("来源历史应为 登记/分装/分装 三条, got %d", len(parent.History))
113		}
114		for i, wantKind := range []string{"register", "split", "split"} {
115			if parent.History[i].Kind != wantKind {
116				t.Fatalf("来源历史顺序错误: %+v", parent.History)
117			}
118		}
119	
120		// 最后一个子样保留实际分出量，来源关系与持有人地点同样一致。
121		last, err := s.GetSample(lastID)
122		if err != nil {
123			t.Fatalf("最后子样应可查询: %v", err)
124		}
125		if last.InitialQty != "0.001" || last.Remaining != "0.001" {
126			t.Fatalf("最后子样数量错误: init=%s remaining=%s", last.InitialQty, last.Remaining)
127		}
128		if last.ParentID != parentID || last.Holder != "张三" || last.Location != "实验室A" {
129			t.Fatalf("最后子样继承关系错误: %+v", last)
130		}
131	
132		// 大整数数量落盘后重新打开仍逐位精确，子样顺序与来源关系不丢。
133		reopened, err := Open(path)
134		if err != nil {
135			t.Fatalf("reopen: %v", err)
136		}
137		rp, err := reopened.GetSample(parentID)
138		if err != nil {
139			t.Fatal(err)
140		}
141		if rp.InitialQty != maxQtyString || rp.Remaining != "0.000" ||
142			rp.Destruction != nil ||
143			len(rp.Children) != 2 || rp.Children[0] != firstID || rp.Children[1] != lastID {
144			t.Fatalf("重开后来源状态不精确: %+v", rp)
145		}
146		rc1, err := reopened.GetSample(firstID)
147		if err != nil {
148			t.Fatal(err)
149		}
150		if rc1.InitialQty != belowMaxString || rc1.Remaining != belowMaxString ||
151			rc1.ParentID != parentID || rc1.Holder != "张三" || rc1.Location != "实验室A" {
152			t.Fatalf("重开后大数量子样状态不精确: %+v", rc1)
153		}
154		rc2, err := reopened.GetSample(lastID)
155		if err != nil {
156			t.Fatal(err)
157		}
158		if rc2.InitialQty != "0.001" || rc2.Remaining != "0.001" || rc2.ParentID != parentID {
159			t.Fatalf("重开后最后子样状态错误: %+v", rc2)
160		}
161	}
162	
163	// TestSplitRejectedWhenTotalOutsideLargeBounds 回归整次分装在大数量下的
164	// 合计拒绝规则：各子样数量分别合法，但合计超出可表示范围时返回 ErrInvalid；
165	// 合计仍在支持范围内、仅比来源剩余量多 0.001 时返回 ErrConflict。
166	// 两类拒绝都必须完全不生效。
167	func TestSplitRejectedWhenTotalOutsideLargeBounds(t *testing.T) {
168		s, _ := openBoundaryStore(t)
169	
170		// --- 场景一：合计超过 9223372036854775.807 的支持上限 ---------------
171		// 两个子样数量分别合法（一个取上限本身，一个取最小合法量），但合计
172		// 超过上限一个最小刻度，int64 累加会回绕；必须判为 ErrInvalid，
173		// 不能把合计误判成一个更小的合法数量而放行。
174		mustRegister(t, s, "BIG", maxQtyString, "张三", "实验室A")
175		bigBefore, err := s.GetSample("BIG")
176		if err != nil {
177			t.Fatal(err)
178		}
179		_, err = s.Split(SplitInput{ParentID: "BIG", Parts: []SplitPart{
180			{ID: "OVF1", Qty: maxQtyString}, // 上限本身，单独合法
181			{ID: "OVF2", Qty: "0.001"},      // 最小合法量，合计 = 上限 + 0.001
182		}})
183		if !errors.Is(err, ErrInvalid) {
184			t.Fatalf("合计超出支持范围应返回 ErrInvalid, got %v", err)
185		}
186		if errors.Is(err, ErrConflict) {
187			t.Fatalf("超出表示范围不能按普通超量处理为 ErrConflict, got %v", err)
188		}
189		if !strings.Contains(err.Error(), "超出可表示范围") {
190			t.Fatalf("错误内容应能看出是合计超出表示范围, got %v", err)
191		}
192	
193		// 被拒绝后来源数量、子样编号、保管历史、持有人地点与待确认状态全部不变。
194		bigAfter, err := s.GetSample("BIG")
195		if err != nil {
196			t.Fatal(err)
197		}
198		if !reflect.DeepEqual(bigAfter, bigBefore) {
199			t.Fatalf("被拒绝分装改动了来源状态:\n before=%+v\n after =%+v", bigBefore, bigAfter)
200		}
201		if bigAfter.Remaining != maxQtyString || bigAfter.InitialQty != maxQtyString {
202			t.Fatalf("被拒绝分装不得扣减来源数量: init=%s remaining=%s",
203				bigAfter.InitialQty, bigAfter.Remaining)
204		}
205		if len(bigAfter.Children) != 0 || len(bigAfter.History) != 1 {
206			t.Fatalf("被拒绝分装不得追加子样编号或保管历史: %+v", bigAfter)
207		}
208		if bigAfter.Holder != "张三" || bigAfter.Location != "实验室A" ||
209			bigAfter.PendingTransfer != nil || bigAfter.Destruction != nil {
210			t.Fatalf("被拒绝分装不得改变持有人、地点及待确认状态: %+v", bigAfter)
211		}
212		for _, id := range []string{"OVF1", "OVF2"} {
213			if got, err := s.GetSample(id); !errors.Is(err, ErrNotFound) {
214				t.Fatalf("被拒绝批次的子样 %s 应查不到, got view=%+v err=%v", id, got, err)
215			}
216		}
217	
218		// --- 场景二：合计仍在支持范围内，但比来源剩余量多 0.001 -------------
219		// 来源初始为上限 - 0.001，先成功分出 0.001（来源剩上限 - 0.002），
220		// 制造拒绝前已存在的子样和保管历史。
221		mustRegister(t, s, "NEAR", belowMaxString, "张三", "实验室A")
222		if _, err := s.Split(SplitInput{ParentID: "NEAR", Parts: []SplitPart{
223			{ID: "E0", Qty: "0.001"},
224		}}); err != nil {
225			t.Fatalf("前置小分装应成功: %v", err)
226		}
227		nearBefore, err := s.GetSample("NEAR")
228		if err != nil {
229			t.Fatal(err)
230		}
231		if nearBefore.Remaining != twoBelowString {
232			t.Fatalf("前置分装后来源应剩余 %s, got %s", twoBelowString, nearBefore.Remaining)
233		}
234	
235		// (上限 - 0.003) + 0.002 = 上限 - 0.001，合计未超支持范围，
236		// 但比来源剩余量（上限 - 0.002）恰好多 0.001。
237		_, err = s.Split(SplitInput{ParentID: "NEAR", Parts: []SplitPart{
238			{ID: "OVR1", Qty: threeBelowStr}, // 上限 - 0.003，单独合法
239			{ID: "OVR2", Qty: "0.002"},       // 合计 上限 - 0.001 <= 上限
240		}})
241		if !errors.Is(err, ErrConflict) {
242			t.Fatalf("合计超过来源剩余量应返回 ErrConflict, got %v", err)
243		}
244		if !strings.Contains(err.Error(), "超过") || !strings.Contains(err.Error(), "剩余量") {
245			t.Fatalf("错误内容应能看出是合计超过来源剩余量, got %v", err)
246		}
247	
248		// 来源数量、子样列表与历史保持在拒绝前；待确认/销毁状态不变。
249		nearAfter, err := s.GetSample("NEAR")
250		if err != nil {
251			t.Fatal(err)
252		}
253		if nearAfter.InitialQty != belowMaxString || nearAfter.Remaining != twoBelowString {
254			t.Fatalf("被拒绝分装不得扣减来源数量: init=%s remaining=%s",
255				nearAfter.InitialQty, nearAfter.Remaining)
256		}
257		if len(nearAfter.Children) != 1 || nearAfter.Children[0] != "E0" {
258			t.Fatalf("拒绝前已存在的子样列表应原样保留: %v", nearAfter.Children)
259		}
260		if len(nearAfter.History) != 2 ||
261			nearAfter.History[0].Kind != "register" || nearAfter.History[1].Kind != "split" {
262			t.Fatalf("拒绝前已存在的保管历史应继续保留: %+v", nearAfter.History)
263		}
264		if nearAfter.Holder != "张三" || nearAfter.Location != "实验室A" ||
265			nearAfter.PendingTransfer != nil || nearAfter.Destruction != nil {
266			t.Fatalf("被拒绝分装不得改变持有人、地点及待确认状态: %+v", nearAfter)
267		}
268	
269		// 拒绝前已经存在的子样继续保留且数量不变；本次拟创建的子样仍查不到。
270		e0, err := s.GetSample("E0")
271		if err != nil {
272			t.Fatalf("拒绝前已存在的子样应继续可查: %v", err)
273		}
274		if e0.InitialQty != "0.001" || e0.Remaining != "0.001" || e0.ParentID != "NEAR" {
275			t.Fatalf("拒绝前已存在的子样状态被改动: %+v", e0)
276		}
277		for _, id := range []string{"OVR1", "OVR2"} {
278			if got, err := s.GetSample(id); !errors.Is(err, ErrNotFound) {
279				t.Fatalf("被拒绝批次的子样 %s 应查不到, got view=%+v err=%v", id, got, err)
280			}
281		}
282	}
