131		}
132		tr, err := s.GetTransfer("T1")
133		if err != nil {
134			t.Fatal(err)
135		}
136		if !tr.Confirmed || tr.ConfirmedBy != "李四" {
137			t.Fatalf("交接应保持李四确认的已确认状态: %+v", tr)
138		}
139	}
140	
141	// TestOpenRestoresConfirmedTransferAndKeepsFacts：正常恢复后按交接编号
142	// 查询仍显示已确认，保留原确认人、接收时间与交接量，无需再次确认接收；
143	// 原样以 10.000 完成交接后分出 3.250 子样、剩余 6.750 又交给另一人，
144	// 旧交接仍按当时的 10.000 与原接收人恢复；样品后来被销毁也不影响旧
145	// 确认信息的有效性。
146	func TestOpenRestoresConfirmedTransferAfterSplitTransferAndDestroy(t *testing.T) {
147		s, hAt1, rAt1, hAt2, rAt2 := setupDivergedHandover(t)
148		if _, err := s.Confirm(ConfirmInput{"TR-002", "王五", "实验室C", rAt2}); err != nil {
149			t.Fatalf("第二次交接接收: %v", err)
150		}
151		if _, err := s.Destroy(DestroyInput{
152			SampleID: "S-001-A", Operator: "李四", Location: "实验室B",
153			At: hAt2.Add(2 * time.Hour), Reason: "子样实验结束按规程销毁",
154		}); err != nil {
155			t.Fatalf("销毁子样: %v", err)
156		}
157	
158		s2, err := Open(s.path)
159		if err != nil {
160			t.Fatalf("含分装、多次交接与销毁的合法历史文件应正常恢复: %v", err)
161		}
162		old, err := s2.GetTransfer("TR-001")
163		if err != nil {
164			t.Fatal(err)
165		}
166		requireOldFirstTransfer(t, old, hAt1, rAt1)
167	
168		second, err := s2.GetTransfer("TR-002")
169		if err != nil {
170			t.Fatal(err)
171		}
172		if !second.Confirmed || second.ConfirmedBy != "王五" || second.ReceivedAt == nil ||
173			!second.ReceivedAt.Equal(rAt2) || second.Qty != "6.750" {
174			t.Fatalf("第二次交接恢复后应仍为已确认并保留接收信息: %+v", second)
175		}
176	
177		// 恢复后不需要再次确认接收：重复提交完全相同的接收信息幂等返回，
178		// 不会另记一次转手。
179		again, err := s2.Confirm(ConfirmInput{"TR-001", "李四", "实验室B", rAt1})
180		if err != nil {
181			t.Fatalf("恢复后的已确认交接重复提交应幂等返回: %v", err)
182		}
183		requireOldFirstTransfer(t, again, hAt1, rAt1)
184		child, err := s2.GetSample("S-001-A")
185		if err != nil {
186			t.Fatal(err)
187		}
188		if child.Destruction == nil {
189			t.Fatalf("子样的销毁信息也应原样保留: %+v", child)
190		}
191	}
